SET LOCAL aidash.scope = 'deployment';
ALTER TABLE public.registry DISABLE TRIGGER marketplace_registry_fence;
UPDATE "registry" SET "metadata" = jsonb_set("metadata", '{config}', ((CASE WHEN "metadata" #>> '{config,cache_mode}' = 'explicit' THEN ("metadata" -> 'config') - 'cache_mode' ELSE "metadata" -> 'config' END) - 'provider_route') || '{"provider":"openai_compatible"}'::jsonb) WHERE ("kind" = 'model') AND ("metadata" #>> '{config,provider}' IN ('openrouter')) AND (COALESCE("metadata" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("metadata" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
UPDATE "registry" SET "metadata" = jsonb_set("metadata", '{config}', jsonb_set("metadata" -> 'config', '{provider}', '"openai_compatible"')) WHERE ("kind" = 'embedding') AND ("metadata" #>> '{config,provider}' IN ('openrouter', 'openai')) AND (COALESCE("metadata" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("metadata" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
ALTER TABLE public.registry ENABLE TRIGGER marketplace_registry_fence;
UPDATE "registry_requests" SET "request" = jsonb_set("request", '{config}', ((CASE WHEN "request" #>> '{config,cache_mode}' = 'explicit' THEN ("request" -> 'config') - 'cache_mode' ELSE "request" -> 'config' END) - 'provider_route') || '{"provider":"openai_compatible"}'::jsonb) WHERE ("request" ->> 'kind' = 'model') AND ("request" #>> '{config,provider}' IN ('openrouter')) AND (COALESCE("request" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("request" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
UPDATE "registry_requests" SET "request" = jsonb_set("request", '{config}', jsonb_set("request" -> 'config', '{provider}', '"openai_compatible"')) WHERE ("request" ->> 'kind' = 'embedding') AND ("request" #>> '{config,provider}' IN ('openrouter', 'openai')) AND (COALESCE("request" #> '{config,provider_credential}', 'null'::jsonb) = 'null'::jsonb AND COALESCE("request" #> '{config,plan_connection}', 'null'::jsonb) = 'null'::jsonb);
